SELECT CASE WHEN quantity >= 9 THEN 'high' WHEN quantity >= 4 THEN 'mid' ELSE 'low' END AS quantity_bucket, order_id, COUNT(DISTINCT quantity) AS unique_orders, COUNT(DISTINCT quantity) AS unique_products, MAX(quantity) - MIN(quantity) AS quantity_range FROM order_items WHERE quantity BETWEEN 3 AND 7 AND order_id IN (12, 16, 39) AND unit_price >= 300 GROUP BY CASE WHEN quantity >= 9 THEN 'high' WHEN quantity >= 4 THEN 'mid' ELSE 'low' END, order_id HAVING COUNT(DISTINCT quantity) > 3 ORDER BY order_id DESC;
